@theme {
  --animate-both: fade 1s,slide 2s;
  --animate-one: zoom 1s, fade 1s;
  @keyframes fade { to { opacity: 0; } }
  @keyframes slide { to { translate: 10px; } }
  @keyframes zoom { to { scale: 2; } }
  @keyframes turn { to { rotate: 1turn; } }
  @keyframes unused { to { opacity: 1; } }
}
.a { animation: turn 1s,unused 1s; }
@tailwind utilities;

