4.0.15.css:
:root, :host {
  --color-red-500: red;
}
.marker\:text-red-500 {
  & *::marker {
    color: var(--color-red-500);
  }
  &::marker {
    color: var(--color-red-500);
  }
}
.marker\:\*\:flex {
  & *::marker {
    :is(& > *) {
      display: flex;
    }
  }
  &::marker {
    :is(& > *) {
      display: flex;
    }
  }
}
.selection\:flex {
  & *::selection {
    display: flex;
  }
  &::selection {
    display: flex;
  }
}
.hover\:marker\:underline {
  &:hover {
    @media (hover: hover) {
      & *::marker {
        text-decoration-line: underline;
      }
      &::marker {
        text-decoration-line: underline;
      }
    }
  }
}

